import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Separator } from "@/components/ui/separator"

export interface FormField {
  id: string
  label: string
  placeholder?: string
  type?: string
  gridCols?: number
}

export interface FormAction {
  label: string
  variant?: "default" | "outline" | "secondary" | "ghost" | "destructive" | "link"
  onClick?: () => void
}

export interface FormBlockProps {
  title?: string
  description?: string
  fields?: FormField[]
  actions?: FormAction[]
}

export function FormBlock({
  title = "Payment Information",
  description = "Enter your payment details to complete the purchase.",
  fields = [
    { id: "card-number", label: "Card Number", placeholder: "1234 5678 9012 3456", type: "text" },
    { id: "expiry", label: "Expiry Date", placeholder: "MM/YY", type: "text", gridCols: 2 },
    { id: "cvv", label: "CVV", placeholder: "123", type: "text", gridCols: 2 },
    { id: "cardholder", label: "Cardholder Name", placeholder: "John Doe", type: "text" },
  ],
  actions = [{ label: "Pay Now", variant: "default" }],
}: FormBlockProps) {
  const gridFields: FormField[] = []
  const regularFields: FormField[] = []

  fields.forEach((field) => {
    if (field.gridCols === 2) {
      gridFields.push(field)
    } else {
      regularFields.push(field)
    }
  })

  return (
    <Card>
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        {regularFields.map((field) => (
          <div key={field.id} className="flex flex-col gap-2">
            <Label htmlFor={field.id}>{field.label}</Label>
            <Input
              id={field.id}
              type={field.type || "text"}
              placeholder={field.placeholder}
            />
          </div>
        ))}
        {gridFields.length > 0 && (
          <div className="grid grid-cols-2 gap-4">
            {gridFields.map((field) => (
              <div key={field.id} className="flex flex-col gap-2">
                <Label htmlFor={field.id}>{field.label}</Label>
                <Input
                  id={field.id}
                  type={field.type || "text"}
                  placeholder={field.placeholder}
                />
              </div>
            ))}
          </div>
        )}
        <Separator />
        {actions.length > 0 && (
          <div className="flex gap-2">
            {actions.map((action, index) => (
              <Button
                key={index}
                variant={action.variant || "default"}
                className={actions.length === 1 ? "w-full" : "flex-1"}
                onClick={action.onClick}
              >
                {action.label}
              </Button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Separator } from "@/components/ui/separator"

export interface MetadataItem {
  label: string
  value: string
}

export interface EntityAction {
  label: string
  variant?: "default" | "outline" | "secondary" | "ghost" | "destructive" | "link"
  onClick?: () => void
}

export interface EntityCardProps {
  name?: string
  role?: string
  status?: string
  avatar?: string | { initials: string }
  metadata?: MetadataItem[]
  actions?: EntityAction[]
}

export function EntityCard({
  name = "John Doe",
  role = "Software Engineer",
  status = "Active",
  avatar = { initials: "JD" },
  metadata = [
    { label: "Member since", value: "Jan 2024" },
    { label: "Projects", value: "12" },
  ],
  actions = [
    { label: "Edit Profile", variant: "outline" },
    { label: "View Details", variant: "default" },
  ],
}: EntityCardProps) {
  const avatarContent =
    typeof avatar === "string" ? (
      <img src={avatar} alt={name} className="h-16 w-16 rounded-full object-cover" />
    ) : (
      <span className="text-2xl font-semibold text-muted-foreground">{avatar.initials}</span>
    )

  return (
    <Card>
      <CardHeader>
        <div className="flex items-start justify-between">
          <div className="flex flex-col gap-1">
            <CardTitle>{name}</CardTitle>
            <CardDescription>{role}</CardDescription>
          </div>
          {status && <Badge variant="secondary">{status}</Badge>}
        </div>
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        <div className="flex items-center gap-4">
          <div className="flex h-16 w-16 items-center justify-center rounded-full bg-muted">
            {avatarContent}
          </div>
          <div className="flex flex-col gap-1">
            <p className="text-sm font-medium">john.doe@example.com</p>
            <p className="text-sm text-muted-foreground">San Francisco, CA</p>
          </div>
        </div>
        {metadata && metadata.length > 0 && (
          <>
            <Separator />
            <div className="flex flex-col gap-2">
              {metadata.map((item, index) => (
                <div key={index} className="flex items-center justify-between text-sm">
                  <span className="text-muted-foreground">{item.label}</span>
                  <span className="font-medium">{item.value}</span>
                </div>
              ))}
            </div>
          </>
        )}
        {actions && actions.length > 0 && (
          <div className="flex gap-2">
            {actions.map((action, index) => (
              <Button
                key={index}
                variant={action.variant || "default"}
                className="flex-1"
                onClick={action.onClick}
              >
                {action.label}
              </Button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Separator } from "@/components/ui/separator"
import { Textarea } from "@/components/ui/textarea"

export interface FormField {
  id: string
  label: string
  placeholder?: string
  type?: string
  rows?: number
}

export interface FormSection {
  fields: FormField[]
  separator?: boolean
}

export interface FormAction {
  label: string
  variant?: "default" | "outline" | "secondary" | "ghost" | "destructive" | "link"
  onClick?: () => void
}

export interface SectionedFormBlockProps {
  title?: string
  description?: string
  sections?: FormSection[]
  actions?: FormAction[]
}

export function SectionedFormBlock({
  title = "Settings",
  description = "Manage your account settings and preferences.",
  sections = [
    {
      fields: [
        { id: "name", label: "Full Name", placeholder: "John Doe", type: "text" },
        { id: "email", label: "Email", placeholder: "john@example.com", type: "email" },
        { id: "bio", label: "Bio", placeholder: "Tell us about yourself", type: "textarea", rows: 4 },
      ],
    },
    {
      separator: true,
      fields: [
        { id: "password", label: "New Password", placeholder: "••••••••", type: "password" },
        {
          id: "confirm-password",
          label: "Confirm Password",
          placeholder: "••••••••",
          type: "password",
        },
      ],
    },
  ],
  actions = [
    { label: "Cancel", variant: "outline" },
    { label: "Save Changes", variant: "default" },
  ],
}: SectionedFormBlockProps) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col gap-6">
        {sections.map((section, sectionIndex) => (
          <div key={sectionIndex} className="flex flex-col gap-4">
            {section.separator && sectionIndex > 0 && <Separator />}
            {section.fields.map((field) => (
              <div key={field.id} className="flex flex-col gap-2">
                <Label htmlFor={field.id}>{field.label}</Label>
                {field.type === "textarea" ? (
                  <Textarea
                    id={field.id}
                    placeholder={field.placeholder}
                    rows={field.rows || 4}
                  />
                ) : (
                  <Input
                    id={field.id}
                    type={field.type || "text"}
                    placeholder={field.placeholder}
                  />
                )}
              </div>
            ))}
          </div>
        ))}
        {actions && actions.length > 0 && (
          <div className="flex justify-end gap-2">
            {actions.map((action, index) => (
              <Button key={index} variant={action.variant || "default"} onClick={action.onClick}>
                {action.label}
              </Button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
