import { Label } from "@/components/ui/label"
import { Separator } from "@/components/ui/separator"
import { Textarea } from "@/components/ui/textarea"

export interface FormField {
  id: string
  label: string
  placeholder?: string
  type?: string
  gridCols?: number
  rows?: number
}

export interface FormCheckbox {
  id: string
  label: string
}

